{
  "status": "Open",
  "current_position": {
    "confirmed": [
      {
        "id": "CP-001",
        "statement": "The slice provides a read-only account review page in a model-driven app showing up to ten active synthetic standard Account rows, ordered by createdon descending, with name and accountnumber displayed.",
        "basis": "The requested user-visible outcome, host, dataset, ordering, limit, and displayed fields are explicit.",
        "source_refs": [
          "Supplied stdin request"
        ]
      },
      {
        "id": "CP-002",
        "statement": "Exact Xrm.WebApi query construction is owned by the approved repository specialist at .agents/skills/dataverse-webapi-query/ and must not be constructed by the orchestration skill.",
        "basis": "The request explicitly requires the approved repository specialist and the incremental-delivery delegation contract assigns Dataverse query construction to that specialist.",
        "source_refs": [
          "power-platform-incremental-delivery package 0.2.0",
          ".agents/skills/dataverse-webapi-query/"
        ]
      },
      {
        "id": "CP-003",
        "statement": "External delegation is enabled, the active client supports explicit specialist selection, and the supplied current approval identifies upstream pin f4bb4ad5bf55e2d50076292bd6301f6337d38083 with approved local-adapter pin 33bc38456abb83f27daad968b748c8085f2a78ef.",
        "basis": "These delegation gate facts and pins were explicitly supplied as current and valid.",
        "source_refs": [
          "Supplied current register approval",
          "Upstream pin f4bb4ad5bf55e2d50076292bd6301f6337d38083",
          "Approved local-adapter pin 33bc38456abb83f27daad968b748c8085f2a78ef"
        ]
      },
      {
        "id": "CP-004",
        "statement": "Only public or synthetic standard Account assumptions may be transferred to the external specialist; tenant access, live metadata, credentials, tokens, and confidential records are excluded.",
        "basis": "The request authorises public and synthetic standard Account assumptions for Xrm.WebApi and supplies no confidential or tenant-specific content.",
        "source_refs": [
          "Supplied stdin request",
          "power-platform-incremental-delivery boundary contract"
        ]
      }
    ],
    "assumptions": [
      {
        "id": "AS-001",
        "statement": "The read-only review experience will use a thin client component hosted by the model-driven app and capable of executing Xrm.WebApi, following the repository's established component and solution-packaging conventions.",
        "impact": "The host component must support loading, empty, error, permission, refresh, responsive, keyboard, and focus states without introducing another data-write path.",
        "validation_required": "Confirm the existing repository component pattern before implementation and package the page and model-driven app navigation changes through the existing solution structure.",
        "source_refs": [
          "Bounded implementation assumption"
        ]
      },
      {
        "id": "AS-002",
        "statement": "The supplied standard Account active-state assumption is sufficient for specialist query construction without tenant metadata inspection.",
        "impact": "The specialist may construct the active-record filter from public standard-schema knowledge but must expose the assumption in its strict JSON answer.",
        "validation_required": "Validate the preserved specialist result against its answer schema, then verify behavior using synthetic inactive and active Account rows in a non-production environment.",
        "source_refs": [
          "Supplied authorisation for public and synthetic standard Account assumptions"
        ]
      },
      {
        "id": "AS-003",
        "statement": "The model-driven app user already has an appropriate least-privilege read entitlement to the Account rows intended for review.",
        "impact": "No new security role or permission change is included; users without access must receive safe permission feedback.",
        "validation_required": "Resolve and verify the target security-role assignment before deployment without transferring role membership or account data to the personal OpenAI zone.",
        "source_refs": [
          "Bounded security assumption"
        ]
      }
    ],
    "open_questions": [
      {
        "id": "OQ-001",
        "question": "Has the externally executed dataverse-webapi-query specialist result been preserved, independently validated, and supplied with its relative path and SHA-256?",
        "owner": "External delegation operator",
        "blocks_ready": true
      }
    ],
    "rejected": [],
    "superseded": []
  },
  "boundary": {
    "zone": "personal-openai",
    "data_classification": "synthetic",
    "cross_zone_transfer": "permitted"
  },
  "slice": {
    "outcome": "A model-driven app user opens Account Review and can review no more than the ten most recently created active synthetic Accounts, in createdon-descending order, with each row showing name and accountnumber.",
    "entry": "Persona: authorised model-driven app reviewer. Host: organisational Microsoft model-driven app. Entry point: Account Review navigation item. Initiating event: opening the page triggers one bounded Xrm.WebApi read and presents an immediate loading state.",
    "validation": "Before rendering, verify that the client API is available and that the response has the expected bounded collection shape. Treat missing optional accountnumber values as displayable empty values, render returned strings as text rather than executable markup, and reject malformed responses safely. Dataverse enforces row and table read permissions. A monotonically increasing request token ensures that an older response cannot replace a newer refresh result.",
    "persistence_or_action": "The slice is read-only and performs no durable write. Dataverse Account is the authoritative data owner, and the client issues one specialist-approved bounded retrieval per page load or explicit refresh. Repeated reads are safe; no acknowledgement, queue, workflow, duplicate write handler, or persistence path is introduced.",
    "feedback": "Show loading while the read is pending; show the ordered name and accountnumber list on success; show a clear empty state when no active rows are returned; provide sanitised permission and general failure states with a retry action; disable or coalesce refresh while appropriate; prevent stale responses from replacing newer results; preserve keyboard focus after refresh; and truncate or wrap long content responsively without hiding accessible text.",
    "telemetry": "Emit a privacy-safe page-load or refresh event containing a generated correlation ID, success, empty, permission-denied, failure, or stale-response-discarded outcome, duration, and returned row count. Exclude account names, account numbers, record identifiers, query response bodies, tenant URLs, user identifiers, credentials, and tokens.",
    "evidence": "Local proof consists of source review and focused component tests. Automated proof consists of query-contract, rendering, error-state, concurrency, accessibility, and packaging checks. Package proof verifies the solution artifact and dependencies. Deployment proof requires authorised import and configuration readback in a non-production organisational Microsoft environment. Runtime proof requires an observed synthetic end-to-end run covering populated, empty, inactive-exclusion, permission, failure, refresh, and stale-response behavior; no lower evidence level proves deployment or runtime behavior.",
    "scope": [
      "One read-only Account Review entry point in a model-driven app",
      "One bounded specialist-approved Xrm.WebApi retrieval",
      "At most ten active synthetic standard Account rows",
      "createdon-descending ordering",
      "Visible name and accountnumber columns",
      "Loading, populated, empty, permission, failure, retry, stale-response, long-content, narrow-layout, keyboard, and focus states",
      "Privacy-safe operational telemetry",
      "Solution packaging, focused tests, deployment prerequisites, and rollback definition"
    ],
    "exclusions": [
      "Account create, update, delete, activation, or deactivation",
      "Pagination beyond the first ten records",
      "Search, filtering controls, sorting controls, export, bulk actions, and inline editing",
      "Custom Account schema or live metadata discovery",
      "Tenant authentication, environment access, deployment, security-role changes, or permission elevation",
      "Confidential, personal, customer, or production account data",
      "AI or Copilot behavior"
    ]
  },
  "architecture": {
    "experience": [
      {
        "id": "EXP-001",
        "decision": "Expose a read-only Account Review page from model-driven app navigation using the repository's established client-component pattern, with semantic list or table markup and complete loading, empty, error, permission, retry, responsive, keyboard, and focus behavior.",
        "rationale": "This is the smallest user-visible host-compatible experience capable of using Xrm.WebApi while keeping business rules and query construction outside presentation rendering.",
        "evidence_status": "Assumption"
      }
    ],
    "data": [
      {
        "id": "DAT-001",
        "decision": "Use the standard Dataverse Account table as the sole source, retrieve only the fields needed by the display, restrict the result to active rows and at most ten records, and order by createdon descending using the exact specialist-produced query.",
        "rationale": "A bounded, projected read minimizes transferred data and directly implements the review outcome.",
        "evidence_status": "Open"
      }
    ],
    "integration": [
      {
        "id": "INT-001",
        "decision": "Use one client-side Xrm.WebApi retrieval on page load or explicit refresh; introduce no connector, flow, plug-in, webhook, queue, duplicate handler, or direct write.",
        "rationale": "The slice is a synchronous read-only review and requires no additional integration lifecycle.",
        "evidence_status": "Confirmed"
      }
    ],
    "ai": [
      {
        "id": "AI-001",
        "decision": "Include no runtime AI, Copilot, prompt, grounding, or model component.",
        "rationale": "The requested outcome is deterministic Account retrieval and display.",
        "evidence_status": "Confirmed"
      }
    ],
    "security": [
      {
        "id": "SEC-001",
        "decision": "Rely on Dataverse table, row, and field read privileges; request no permission changes; render returned values as inert text; and keep telemetry free of account content and environment-specific identifiers.",
        "rationale": "This preserves least privilege, prevents client-side content injection, and keeps operational evidence within the approved data boundary.",
        "evidence_status": "Assumption"
      }
    ],
    "operations": [
      {
        "id": "OPS-001",
        "decision": "Use correlation-based privacy-safe telemetry for load, refresh, empty, permission, failure, and stale-response outcomes, with no Account payload logging.",
        "rationale": "Operators need diagnosable outcomes without exposing synthetic row content or creating a second data store.",
        "evidence_status": "Assumption"
      }
    ],
    "alm": [
      {
        "id": "ALM-001",
        "decision": "Package the client component and model-driven app navigation reference in the existing solution, preserve environment-neutral configuration, validate dependencies before import, and deploy through the repository's authorised non-production ALM path.",
        "rationale": "The slice must be reviewable, reproducible, and removable without manual unmanaged target edits.",
        "evidence_status": "Assumption"
      }
    ]
  },
  "delegations": [
    {
      "id": "DEL-001",
      "specialist": ".agents/skills/dataverse-webapi-query/",
      "source_type": "upstream",
      "phase": "requested",
      "registry": {
        "path": "canonical upstream specialist register entry for .agents/skills/dataverse-webapi-query/",
        "entry_status": "current-approved",
        "version_or_pin": "f4bb4ad5bf55e2d50076292bd6301f6337d38083",
        "verified_on": "2026-07-20"
      },
      "request": {
        "scope": "Construct the exact strict-JSON Xrm.WebApi retrieval shape for the bounded synthetic standard Account review requirement only.",
        "data_classification": "synthetic",
        "zone": "personal-openai",
        "permitted_tools": []
      },
      "handoff": {
        "invocation_mode": "explicit-external",
        "input_payload": "Construct the Dataverse Xrm.WebApi query for a synthetic model-driven Account Review slice. The query must retrieve at most ten active rows from the public standard Account table, order them by createdon descending, and project only name and accountnumber for display. Public and synthetic standard Account assumptions are authorised. Return exactly one strict JSON answer conforming to .agents/skills/dataverse-webapi-query/references/answer-output.schema.json, including the exact Xrm.WebApi query shape and any bounded standard-schema assumptions. Do not access a tenant, inspect live metadata, request or expose credentials, tokens, tenant URLs, confidential records, or execute any tool or operation.",
        "expected_output_schema": ".agents/skills/dataverse-webapi-query/references/answer-output.schema.json",
        "continuation_instruction": "In a fresh external thread, explicitly select $dataverse-webapi-query in the host configuration and pass only handoff.input_payload. Preserve the specialist's complete first output unchanged as a standalone relative-path result file, independently validate the complete output against .agents/skills/dataverse-webapi-query/references/answer-output.schema.json, compute its SHA-256, and then resume $power-platform-incremental-delivery with the original orchestration state plus the preserved result path and SHA-256. Do not pass this complete Skill 6 request to the specialist and do not execute or simulate the specialist inside Skill 6."
      },
      "control": {
        "enabled": true,
        "selection_mode": "none",
        "selector": "$dataverse-webapi-query",
        "client_compatible": true,
        "prerequisites_satisfied": true,
        "boundary_permitted": true,
        "permissions_approved": true
      },
      "execution": {
        "execution_observed": false,
        "result_schema_valid": null,
        "invoked": false,
        "outcome_status": "open",
        "result_reference": ""
      },
      "verification": {
        "specialist_identity_verified": true,
        "register_verified": true,
        "input_classification_verified": true,
        "boundary_verified": true,
        "result_hash_verified": null,
        "result_schema_verified": null,
        "untrusted_input_checked": null,
        "override_attempted": false,
        "result_sha256": "",
        "source_path": ""
      },
      "evidence_refs": [
        "Supplied current upstream approval pin f4bb4ad5bf55e2d50076292bd6301f6337d38083",
        "Supplied approved local-adapter provenance pin 33bc38456abb83f27daad968b748c8085f2a78ef",
        "Supplied explicit delegation enablement and compatible-client confirmation",
        "Supplied authorisation for public and synthetic standard Account assumptions"
      ],
      "open_items": [
        "External execution has not been observed.",
        "No preserved standalone specialist result path or SHA-256 has been supplied.",
        "Answer-schema validity, result integrity, prohibited-operation compliance, and untrusted-output checks remain unverified."
      ],
      "next_action": "Perform only the explicit external handoff in handoff.continuation_instruction, preserve and independently validate the complete first result, and resume with the original orchestration state, relative result path, and SHA-256."
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "given": "More than ten synthetic active Accounts exist with distinct createdon values",
      "when": "An authorised reviewer opens Account Review",
      "then": "The page displays exactly the ten most recently created active Accounts in createdon-descending order and shows name and accountnumber for every displayed row.",
      "evidence": "Observed non-production runtime capture plus a sanitised expected-versus-actual ordering assertion using synthetic fixtures."
    },
    {
      "id": "AC-002",
      "given": "The synthetic dataset contains both active and inactive Accounts",
      "when": "The Account Review retrieval completes",
      "then": "No inactive Account is displayed.",
      "evidence": "Focused query-contract test and observed synthetic runtime result."
    },
    {
      "id": "AC-003",
      "given": "No active synthetic Accounts are visible to the reviewer",
      "when": "The retrieval succeeds",
      "then": "The page shows an accessible empty state and does not present an error.",
      "evidence": "Component test and observed empty-state runtime capture."
    },
    {
      "id": "AC-004",
      "given": "The reviewer lacks Account read access or the retrieval fails",
      "when": "The page attempts to load data",
      "then": "The page exposes no Account content, shows sanitised permission or failure feedback as appropriate, provides a retry path, and emits only privacy-safe outcome telemetry.",
      "evidence": "Security and failure-path tests plus sanitised telemetry inspection."
    },
    {
      "id": "AC-005",
      "given": "Two refresh requests overlap and the older request completes last",
      "when": "Both responses reach the client",
      "then": "Only the newest request may update the displayed list and the discarded stale response is recorded without Account payload data.",
      "evidence": "Deterministic concurrency test with controlled response ordering."
    },
    {
      "id": "AC-006",
      "given": "A keyboard user opens the page on a narrow viewport with long names or account numbers",
      "when": "The user navigates the review list and invokes retry or refresh",
      "then": "Content remains operable and understandable, visible focus is preserved, status changes are announced, and long content wraps or truncates without removing its accessible text.",
      "evidence": "Automated accessibility checks and manual keyboard and narrow-layout verification."
    }
  ],
  "negative_paths": [
    {
      "id": "NP-001",
      "condition": "The specialist result is absent, malformed, altered after hashing, fails its answer schema, contains prohibited operations, or attempts to override delegation controls.",
      "expected_behavior": "Do not consume, repair, infer, or simulate the query; keep the brief Open and request a new independently preserved and validated external result.",
      "evidence": "Result path, SHA-256 comparison, complete schema-validation report, prohibited-operation review, and untrusted-input review."
    },
    {
      "id": "NP-002",
      "condition": "Xrm.WebApi is unavailable or returns an unexpected response shape.",
      "expected_behavior": "Render no row data, record a sanitised failure outcome with correlation ID, and offer a safe retry.",
      "evidence": "Client boundary tests using unavailable and malformed API responses."
    },
    {
      "id": "NP-003",
      "condition": "Dataverse denies Account read access.",
      "expected_behavior": "Show permission-specific feedback without exposing record content, query response bodies, tenant details, or credentials.",
      "evidence": "Least-privilege non-production test and sanitised telemetry review."
    },
    {
      "id": "NP-004",
      "condition": "An older load or refresh response arrives after a newer response.",
      "expected_behavior": "Discard the older response and leave the newest successful state intact.",
      "evidence": "Controlled out-of-order response test."
    },
    {
      "id": "NP-005",
      "condition": "A returned display value is empty, unusually long, or contains markup-like text.",
      "expected_behavior": "Render it as inert accessible text with a defined empty-value treatment and without layout-breaking or script execution.",
      "evidence": "Rendering, injection-safety, long-content, and narrow-viewport tests."
    }
  ],
  "tests": [
    {
      "id": "TEST-001",
      "class": "functional",
      "scope": "Validate the externally supplied query contract for standard Account, active-only filtering, maximum ten rows, createdon-descending ordering, and name and accountnumber projection.",
      "expected": "The preserved specialist output is schema-valid and the implementation uses its approved query shape without locally inventing or broadening the query.",
      "evidence_required": "Preserved specialist result, SHA-256 verification, answer-schema report, and focused query-contract test output.",
      "status": "not-run"
    },
    {
      "id": "TEST-002",
      "class": "functional",
      "scope": "Render populated, fewer-than-ten, exactly-ten, more-than-ten, and empty synthetic datasets.",
      "expected": "Only the bounded active result appears in the required order with name and accountnumber displayed.",
      "evidence_required": "Automated component results and synthetic expected-versus-actual assertions.",
      "status": "planned"
    },
    {
      "id": "TEST-003",
      "class": "security",
      "scope": "Exercise denied read access, markup-like field values, and telemetry redaction.",
      "expected": "No unauthorised content or executable markup is exposed and telemetry contains no Account payload or environment-specific sensitive values.",
      "evidence_required": "Security test output and sanitised telemetry-field inspection.",
      "status": "planned"
    },
    {
      "id": "TEST-004",
      "class": "reliability",
      "scope": "Exercise retry, API failure, malformed response, repeated refresh, and out-of-order completion.",
      "expected": "The page recovers safely, avoids duplicate unbounded requests, and only the latest request updates visible state.",
      "evidence_required": "Deterministic mocked-response test results.",
      "status": "planned"
    },
    {
      "id": "TEST-005",
      "class": "accessibility",
      "scope": "Check semantic structure, accessible names, loading and error announcements, keyboard operation, focus preservation, long content, and narrow layouts.",
      "expected": "The review journey is operable and understandable without a pointer and has no serious automated accessibility violations.",
      "evidence_required": "Automated scan plus documented manual keyboard and responsive checks.",
      "status": "planned"
    },
    {
      "id": "TEST-006",
      "class": "performance",
      "scope": "Confirm initial load and refresh each issue one bounded retrieval and render no more than ten rows.",
      "expected": "No unbounded fetch, client-side full-table retrieval, or duplicate request loop occurs.",
      "evidence_required": "Network trace from synthetic non-production execution and row-count assertion.",
      "status": "planned"
    },
    {
      "id": "TEST-007",
      "class": "alm",
      "scope": "Validate solution contents, app navigation dependency, component references, environment-neutral configuration, and absence of secrets or tenant-specific values.",
      "expected": "The solution artifact is deterministic, dependency-complete, and contains no prohibited environment-specific material.",
      "evidence_required": "Solution diff, static validation output, and package integrity report.",
      "status": "planned"
    },
    {
      "id": "TEST-008",
      "class": "deployment",
      "scope": "Import into an authorised non-production organisational Microsoft environment and read back the Account Review navigation and component configuration.",
      "expected": "The package imports without unresolved dependencies and the configured entry point is available to the intended test role.",
      "evidence_required": "Observed import result and configuration readback.",
      "status": "not-run"
    },
    {
      "id": "TEST-009",
      "class": "rollback",
      "scope": "Remove or revert the Account Review navigation and component through the approved solution rollback path.",
      "expected": "The prior app navigation is restored without changing Account data or unrelated app components.",
      "evidence_required": "Non-production rollback execution record and post-rollback configuration readback.",
      "status": "not-run"
    }
  ],
  "deployment": {
    "authorization_status": "not-requested",
    "target_zone": "organisational-microsoft",
    "environments": [
      "An authorised non-production organisational Microsoft Dataverse environment containing synthetic standard Account test rows",
      "Production only after separate deployment authorisation and successful non-production evidence"
    ],
    "prerequisites": [
      "A preserved specialist result with verified SHA-256, complete answer-schema validity, and passed untrusted-output checks",
      "Confirmed repository component and solution-packaging conventions",
      "An existing model-driven app and authorised navigation extension point",
      "A least-privilege test role with Account read access and a negative-test role without that access",
      "Synthetic active and inactive Account fixtures covering ordering, limit, empty, missing accountnumber, long-content, and markup-like text cases",
      "An approved privacy-safe telemetry destination or an explicit no-sink configuration",
      "Separate deployment authorisation"
    ],
    "steps": [
      "Implement the thin read-only component using the validated specialist query and repository patterns",
      "Run focused functional, security, reliability, accessibility, performance, and ALM checks",
      "Build and inspect the solution artifact and its dependencies",
      "Obtain explicit non-production deployment authorisation",
      "Import through the approved ALM path and configure the Account Review navigation entry",
      "Read back configuration and execute the synthetic runtime acceptance suite"
    ],
    "post_deploy_checks": [
      "Confirm the navigation entry opens for the intended test role",
      "Confirm maximum-ten, active-only, createdon-descending behavior with synthetic fixtures",
      "Confirm name and accountnumber rendering in populated and empty states",
      "Confirm safe permission, failure, retry, and out-of-order refresh behavior",
      "Confirm privacy-safe telemetry and absence of Account payload logging",
      "Confirm no Account writes, flows, plug-ins, webhooks, or duplicate handlers were introduced"
    ],
    "evidence_required": [
      "Authorised import result",
      "Configuration and dependency readback",
      "Synthetic runtime acceptance evidence",
      "Sanitised telemetry evidence",
      "Security-role behavior evidence",
      "Package hash and solution diff"
    ]
  },
  "rollback": {
    "triggers": [
      "Solution import or dependency validation fails",
      "The review page returns inactive, incorrectly ordered, over-limit, or over-projected data",
      "Permission boundaries are bypassed or Account content appears in telemetry",
      "The page becomes inaccessible, traps focus, or cannot recover from loading and failure states",
      "Repeated or stale requests produce incorrect visible state",
      "An unintended Account write or additional lifecycle handler is detected"
    ],
    "steps": [
      "Disable or remove the Account Review navigation entry through the approved solution path",
      "Revert to the previous validated solution version",
      "Verify that the prior model-driven app navigation and unrelated components remain intact",
      "Confirm that no Account data changed because the slice is read-only",
      "Preserve sanitised failure and rollback evidence for diagnosis before any re-release"
    ],
    "data_considerations": [
      "The slice performs no Account writes, so rollback requires no business-data restoration",
      "Do not retain Account names, account numbers, response bodies, or tenant-specific identifiers in rollback evidence",
      "Retain only package identifiers, correlation IDs, outcome codes, hashes, and sanitised validation results"
    ],
    "owner": "Authorised organisational Microsoft solution release owner",
    "evidence_required": [
      "Rollback authorisation",
      "Previous-version import or configuration result",
      "Post-rollback navigation and dependency readback",
      "Confirmation that Account data was unchanged",
      "Sanitised rollback test record"
    ]
  },
  "next_action": "In a fresh external thread, explicitly select $dataverse-webapi-query and pass only DEL-001.handoff.input_payload; preserve its complete first output unchanged, independently validate it against .agents/skills/dataverse-webapi-query/references/answer-output.schema.json, compute its SHA-256, and resume $power-platform-incremental-delivery with this complete original orchestration state plus the relative result path and SHA-256. No specialist execution, simulation, query substitution, implementation, tenant access, or deployment is authorised in the current phase."
}
